        m = re.match(r'''https://ocfl.io/(\d+.\d)/spec/#inventory''', inventory['type'])
        if not m:
            self.error('E038b', got=inventory['type'], assumed_spec_version=self.spec_version)
        elif m.group(1) in self.spec_versions_supported:
