    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    args = list(args)
    if not args:
        args = list(self.args)
    i = 0
    while i < len(args):
